# Panel bounds use inclusive row/column starts; each is a 5x5 frame.
panels = [
    {'name':'A','r':1,'c':5,'frame':2,'center':1},
    {'name':'B','r':4,'c':0,'frame':2,'center':7},
    {'name':'F','r':2,'c':12,'frame':8,'center':1},
    {'name':'C','r':8,'c':13,'frame':2,'center':3},
    {'name':'D','r':10,'c':4,'frame':2,'center':6},
    {'name':'H','r':16,'c':1,'frame':8,'center':9},
    {'name':'E','r':15,'c':9,'frame':2,'center':4},
    {'name':'G','r':14,'c':15,'frame':8,'center':6},
]
# Simulate horizontal packing within each direction group, preserving the order of boxes that overlap vertically.
for p in sorted((p for p in panels if p['frame']==2), key=lambda p:p['c'], reverse=True):
    right_limit=17
    for q in panels:
        if q is p or q['frame']!=2 or q['c']<=p['c']:
            continue
        if p['r'] <= q['r']+4 and q['r'] <= p['r']+4:
            right_limit=min(right_limit, q['final_c']-5)
    p['final_c']=right_limit
for p in sorted((p for p in panels if p['frame']==8), key=lambda p:p['c']):
    left_limit=0
    for q in panels:
        if q is p or q['frame']!=8 or q['c']>=p['c']:
            continue
        if p['r'] <= q['r']+4 and q['r'] <= p['r']+4:
            left_limit=max(left_limit, q['final_c']+5)
    p['final_c']=left_limit
[(p['name'],p['r'],p['c'],p['frame'],p['final_c']) for p in panels]
